  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Chatta con un modello a tua scelta; {mnemo} legge, scrive, tagga, collega, sposta e riordina le note con gli strumenti di Memora. Non può navigare sul web, eseguire comandi, eliminare per sempre né modificare il server. Le chiavi sono protette su questo server e non vengono mai inviate al browser.",
