  "Claude Desktop (older)": "Claude Desktop (versione precedente)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude e ChatGPT accedono con il tuo account Memora. Niente da copiare.",
  "Claude models": "Modelli Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude accede tramite OAuth, quindi non si incolla nessuna chiave: ne riceve una propria quando premi Consenti. Senza accesso, collegalo come <b>Altra app</b> e invia l'intestazione <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor e altri",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor e altri, ognuno con la sua chiave",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex e altri hanno ciascuno il proprio accesso, così vedi cosa fa ognuno.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT e il tuo agente condividono un solo Memora, raggiungibile da questo computer, dalla rete locale o da internet",
