  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "Le chat eliminate e i loro messaggi spariscono per sempre. Le tue note non vengono toccate e una chat che sta rispondendo ora viene lasciata stare.",
  "Deleted notes": "Note eliminate",
  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "Le note eliminate restano qui finché non le ripristini o le elimini per sempre. Quando ripristini, scegli dove va la nota: la vecchia cartella, un'altra cartella o il livello principale.",
