  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Trascina una scheda in un altro riquadro cartella per spostare la nota su disco. Trascina un riquadro dal suo nome per riorganizzare la lavagna; rilascialo su un altro riquadro per spostarvi l'intera cartella. Doppio clic su un titolo per rinominare. Su touch: trascina per muoverti, pizzica per zoomare, tieni premuta una scheda per spostarla, tocca per l'anteprima.",
  "Drag a note here to pin it": "Trascina qui una nota per fissarla",
  "Drag notes or folders here to pin them": "Trascina qui note o cartelle per fissarle",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Trascina note o cartelle su una cartella per spostarle, su Fissati per fissarle.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Trascina le note · doppio clic per fissare · / cerca · #tag trova i tag · F adatta · 1 2 3 disposizioni",
  "Drag to move the folder frame; double-click to rename": "Trascina per spostare il riquadro cartella; doppio clic per rinominare",
  "Drag to move the lane. Double click the name to rename it.": "Trascina per spostare la colonna. Fai doppio clic sul nome per rinominarla.",
  "Drag to resize · double-click to reset": "Trascina per ridimensionare · doppio clic per reimpostare",
  "Drag to turn · scroll to zoom · click a point to open its note": "Trascina per ruotare · scorri per zoomare · clicca un punto per aprire la nota",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Trascina per ruotare · scorri per zoomare · clicca un punto per aprire la nota · / per cercare · #tag trova i tag",
  "Draw a chart of how many notes I write each week": "Disegna un grafico di quante note scrivo ogni settimana",
  "Draw this note as a diagram": "Disegna questa nota come diagramma",
  "Drop a card here or add one": "Trascina qui una scheda o aggiungine una",
  "Drop here to hide": "Rilascia qui per nascondere",
  "Drop on a folder": "Rilascia su una cartella",
  "Due": "Scadenza",
  "Due date": "Scadenza",
  "Due date: red when late, amber when soon, green later.": "Scadenza: rosso se superata, ambra se vicina, verde se più avanti.",
  "Duplicate": "Duplica",
