  "Dusk": "Tramonto",
  "Dyslexic": "Dislessia",
  "Each AI app connects over MCP with its own key and permissions.": "Ogni app AI si collega via MCP con la sua chiave e i suoi permessi.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Ogni app AI che connetti è un agente con la propria chiave, così vedi cosa fa ognuna e puoi disattivarne una da sola.",
  "Each agent": "Ogni agente",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Ogni agente appartiene a un'app. Per un'altra app o dispositivo, crea un nuovo agente.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Ogni agente appartiene a un'app. Per usare Memora in un'altra app, crea un agente separato.",
  "Each app gets its own key": "Ogni app ha la sua chiave",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Ognuno ha un id breve che non cambia mai, così i nomi possono cambiare liberamente. Mnemo li prepara, cambia istruzioni o modello, scrive loro, li aspetta, li ferma, li conclude e li rimuove, uno alla volta o tutti insieme, e può lasciarli lavorare in background. Ogni scheda mostra Istruzione, Attività e Risposta.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Ogni tipo è misurato sul proprio spazio: il suo limite se impostato, altrimenti quanto usa più lo spazio libero su disco{disk}. Limite vuoto: nessuno.",
  "Each one gets its own key from Memora.": "Ognuno riceve da Memora la propria chiave.",
  "Earlier": "Precedente",
