  "Embed in a note…": "Incorpora in una nota…",
  "Embed new or existing boards in a note and work on each right there, or put a board into any note from its ⋯ menu; a plain link reads as a small card.": "Incorpora bacheche nuove o esistenti in una nota e lavora su ciascuna lì stesso, oppure metti una bacheca in qualsiasi nota dal suo menu ⋯; un semplice link appare come una piccola scheda.",
  "Emoji icon": "Icona emoji",
