  "Empty trash": "Svuota Cestino",
  "End every session except this one. Those browsers must sign in again.": "Termina tutte le sessioni tranne questa. Quei browser dovranno accedere di nuovo.",
  "End group": "Fine gruppo",
  "End the pause on the server": "Termina la sospensione sul server",
