  "Enter a username.": "Inserisci un nome utente.",
  "Enter an address or a web address first.": "Inserisci prima un indirizzo o un indirizzo web.",
  "Enter an address or a web address, then test.": "Inserisci un indirizzo o un indirizzo web, poi prova.",
  "Enter the code here": "Inserisci qui il codice",
  "Enter the folder path.": "Inserisci il percorso della cartella.",
  "Enter the reset code": "Inserisci il codice di reset",
  "Enter the setup code": "Inserisci il codice di configurazione",
  "Enter your Memora password": "Inserisci la tua password di Memora",
  "Enter your current password.": "Inserisci la password attuale.",
  "Enter your password": "Inserisci la tua password",
  "Entries": "Voci",
  "Error": "Errore",
  "Error 404": "Errore 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Anche con uso quotidiano, un browser accede di nuovo dopo questo tempo. Non può essere inferiore al tempo di inattività.",
  "Every AI loses {n} tool at once. Asks first.": "Ogni AI perde {n} strumento subito. Chiede prima.",
  "Every AI loses {n} tools at once. Asks first.": "Ogni AI perde {n} strumenti subito. Chiede prima.",
  "Every Kanban board in your notes": "Ogni bacheca Kanban nelle tue note",
  "Every action, newest first": "Ogni azione, dalla più recente",
  "Every action, newest first, with search and filters.": "Ogni azione, dalla più recente, con ricerca e filtri.",
  "Every address from one to another.": "Ogni indirizzo dall'uno all'altro.",
  "Every address from the first to the last, joined by a dash.": "Ogni indirizzo dal primo all'ultimo, uniti da un trattino.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Ogni agente di solito parte da zero. {bold} collega ogni agente una volta e tutti leggono lo stesso vault e ci scrivono, così ciò che uno impara, gli altri possono usarlo.",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Ogni bacheca con le sue colonne e il suo avanzamento. Nuova bacheca si trova ovunque ci sia Nuova nota: la barra laterale, Panoramica, le cartelle, i menu, la ricerca e il tasto B.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Ogni browser e agente viene disconnesso finché qualcuno non riavvia Memora su quella macchina. Questa pagina non può riavviarlo.",
  "Every call shows up live in the brain and Activity": "Ogni chiamata compare in tempo reale nel cervello e nell'Attività",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Ogni modifica di Mnemo compare nell'Attività e si può annullare dalla Cronologia.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Ogni modifica, tua o di un'app, compare nell'Attività e si può annullare dalla Cronologia.",
  "Every chat is archived.": "Ogni chat è archiviata.",
  "Every chat with your notes agent": "Ogni chat con l'agente delle tue note",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Ogni AI connessa perde tutti i {n} strumenti subito e non può più leggere né modificare le tue note finché non riattivi gli strumenti qui.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Ogni AI connessa lo perde subito. Puoi riattivarlo quando vuoi.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Ogni AI connessa li perde subito. Puoi riattivarli quando vuoi.",
  "Every connected agent loses its memory until Memora runs again.": "Ogni agente connesso perde la sua memoria finché Memora non riparte.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Ogni dispositivo di una rete domestica o d'ufficio, scritto come indirizzo/dimensione: 192.168.1.0/24 copre da 192.168.1.0 a 192.168.1.255.",
  "Every device on a home or office network.": "Ogni dispositivo di una rete domestica o d'ufficio.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Ogni immagine nella cartella delle note e dove viene mostrata, più le immagini conservate per le chat di Mnemo.",
  "Every image is used in a note.": "Ogni immagine è usata in una nota.",
  "Every note": "Ogni nota",
  "Every note and link, in 3D, as a graph or on a board.": "Ogni nota e link, in 3D, come grafo o su una lavagna.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Ogni nota e sottocartella in \"{path}\" va in {folder}; poi \"{name}\" viene rimossa. Se un nome è già occupato, gli viene aggiunto un numero.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Ogni nota diventa qui una scheda, dentro un riquadro per la sua cartella. La guida mostra come far salvare qui le conoscenze a un'AI, o come scrivere tu una nota.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Ogni nota diventa qui un punto luminoso, raggruppato per cartella. La guida mostra come far salvare qui le conoscenze a un'AI, o come scrivere tu una nota.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Ogni nota con il tag #{tag} ({notes}) riceve il nuovo nome, anche i #tag nel testo.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Ogni nota con i tag {tags} riceve un solo tag al loro posto ({notes}). Cambiano anche i #tag nel testo. Non c'è un annulla in un passaggio; ogni nota conserva la sua cronologia.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Ogni lettura e scrittura di un agente appare in diretta, così sai sempre chi ha fatto cosa.",
  "Every request that reaches this rule is {verb}.": "Ogni richiesta che raggiunge questa regola viene {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Ogni richiesta. Mettila per ultima, per intercettare ciò che le regole sopra non hanno preso.",
  "Every setting and where it lives.": "Ogni impostazione e dove si trova.",
  "Every shortcut in the web UI.": "Ogni scorciatoia dell'interfaccia web.",
  "Every tag and its notes": "Ogni tag e le sue note",
  "Every tool agents can call": "Ogni strumento che gli agenti possono chiamare",
  "Every tool that is on for the server, including new ones.": "Ogni strumento attivo per il server, compresi i nuovi.",
