  "For authentication choose <b>OAuth</b>, leave the client ID and secret empty, and click <b>Create</b>. A Memora page opens: press <b>Allow</b>.": "Per l'autenticazione scegli <b>OAuth</b>, lascia vuoti l'ID client e il secret e clicca <b>Crea</b>. Si apre una pagina di Memora: premi <b>Consenti</b>.",
