  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Raccolta dell'attività reale per {range}. Con un registro grande può volerci un momento, attendi.",
  "General": "Generali",
  "Get a one-time code on the server": "Ottieni un codice monouso sul server",
  "Get started": "Inizia",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Conoscimi attraverso le mie note. Esplora il mio vault (note recenti, diari, progetti, tutto ciò che mi riguarda) e conserva ciò che impari con remember_owner: chi sono, su cosa lavoro, come mi piace ricevere le risposte, cosa mi piace. Solo cose brevi e durature, mai segreti. Poi dimmi in poche righe cosa hai conservato.",
  "Gets its own agent key: read and write nodes over MCP": "Riceve la sua chiave agente: legge e scrive nodi via MCP",
  "Getting started": "Per iniziare",
  "GitHub answered HTTP {code}": "GitHub ha risposto HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Dai a Claude, Cursor o a qualsiasi app MCP la sua chiave, poi lascia che salvi ciò che sa già di te.",
  "Give a key read-only access, or let it write too.": "Dai a una chiave l'accesso in sola lettura, oppure permetti anche di scrivere.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Dai a ogni app o dispositivo il proprio agente. Attività mostra esattamente chi ha fatto cosa, e puoi disattivarne uno senza toccare gli altri.",
  "Give it a name you recognise": "Dagli un nome che riconosci",
