  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Quanto spazio occupano note, immagini e chat di Mnemo, ciascuno rispetto al proprio spazio. Un avviso segnala quando uno è quasi pieno.",
