  "Identity": "Identità",
  "Idle": "Inattivo",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Se ti è stato utile, una stella su GitHub o un passaparola aiuta altri a trovarlo. Nessun problema se no.",
