  "Import and export": "Importa ed esporta",
  "Imported": "Importato",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "In ChatGPT apri <b>Settings → Apps &amp; Connectors → Advanced settings</b> e attiva <b>Developer mode</b>. Poi scegli <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "In Claude (web o desktop) apri <b>Settings → Connectors</b> e scegli <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "In Claude Desktop apri <b>Settings → Developer → Edit Config</b>. Nelle versioni più recenti scegli invece <b>Claude</b>.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "In Windsurf apri <b>Settings → Cascade → MCP servers</b> e scegli <b>View raw config</b>.",
