  "It becomes your first rule.": "Diventa la tua prima regola.",
  "It becomes {path}. Links to its notes keep working.": "Diventa {path}. I link alle sue note continuano a funzionare.",
  "It can change notes, but nothing lets it connect.": "Può modificare le note, ma niente le permette di connettersi.",
  "It can search and read your notes, but not change them": "Può cercare e leggere le tue note, ma non modificarle",
