  "It can {list}.": "Può {list}.",
  "It cannot do anything yet": "Non può ancora fare nulla",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "Ha il controllo totale: legge e modifica le note e può gestire Memora e altri agenti",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Contiene {n} nota. Poi scegli cosa farne: spostarla in un'altra cartella o nel Cestino. Per ora non cambia nulla.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Contiene {n} note. Poi scegli cosa farne: spostarle in un'altra cartella o nel Cestino. Per ora non cambia nulla.",
  "It is added at the end, as rule {n}, so it is checked last.": "Viene aggiunta in fondo, come regola {n}, quindi è verificata per ultima.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Sparisce quando esci, immagini comprese. Le modifiche alle note restano in Attività e Cronologia.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "È custodita bloccata sul server. Inserisci la password di Memora e i pulsanti qui sotto la inseriscono per te.",
  "It is taking a while. Check the server, then reload this page.": "Ci sta mettendo un po'. Controlla il server, poi ricarica questa pagina.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Esce solo dall'elenco Fissati; la cartella resta dov'è.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Esce solo dall'elenco Fissati; la nota resta dov'è.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Potrebbe essere stata rinominata, spostata o eliminata. Le note eliminate aspettano nel Cestino.",
  "It moves; links to it are updated and pins follow.": "Si sposta; i link vengono aggiornati e i fissati la seguono.",
  "It must sign in again and is told why": "Deve accedere di nuovo e ne viene spiegato il motivo",
  "It prints a one-time code. This page moves on by itself.": "Stampa un codice monouso. Questa pagina prosegue da sola.",
  "It reached Memora but did not finish. It often works on the next try.": "Ha raggiunto Memora ma non ha finito. Spesso funziona al tentativo successivo.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Ha raggiunto Memora ma non ha finito: {error} Spesso funziona al tentativo successivo.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Appare con questo nome in Attività, nel cervello e nel grafo. Chiamalo come il dispositivo se usi {app} in più posti, ad esempio \"{example}\".",
  "It was shown when it was made. Make a new key to see one again.": "È stata mostrata alla creazione. Crea una nuova chiave per vederne una di nuovo.",
  "Italic": "Corsivo",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "La sua chiave API e i suoi modelli vengono rimossi. Le chat restano; una chat che usava uno dei suoi modelli passa a quello predefinito.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "La sua chiave e il suo accesso restano uguali in ogni cartella di note. Connettine un altro quando vuoi.",
  "Its key is filled in on the next step": "La sua chiave viene inserita al passaggio successivo",
  "Its key is refused until you turn it back on. Nothing is deleted.": "La sua chiave viene rifiutata finché non lo riattivi. Non viene eliminato nulla.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "La sua chiave viene rifiutata. Attivalo per farlo connettere di nuovo con la stessa chiave.",
  "Its key stopped working. You can restore it until you reload the app.": "La sua chiave ha smesso di funzionare. Puoi ripristinarlo finché non ricarichi l'app.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "La sua chiave smette subito di funzionare. L'attività passata resta; puoi ripristinarlo finché non ricarichi l'app.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "La sua chiave è stata mostrata una sola volta, alla creazione. Una nuova chiave la sostituisce e la vecchia smette subito di funzionare.",
  "Its notes are in its folders. You can also start one here.": "Le sue note sono nelle sue cartelle. Puoi anche iniziarne una qui.",
  "Its numbers, timeline and export.": "I suoi numeri, la cronologia e l'esportazione.",
  "Its old folder is not known, so it goes to the top level": "La sua vecchia cartella non è nota, quindi va al livello principale",
  "Its page": "La sua pagina",
  "Its page shows how to connect it.": "La sua pagina mostra come connetterlo.",
  "Its page: status, recent calls, access and settings.": "La sua pagina: stato, chiamate recenti, accesso e impostazioni.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "I suoi permessi sono una combinazione personalizzata. Scegli un livello per sostituirli o perfezionali in Avanzate.",
