  "Lanes fade at the edge while there is more to see, snap one at a time on phones with dots to jump between them, and links, tags and mentions on cards show as chips.": "Le colonne sfumano sul bordo finché c'è altro da vedere, sul telefono scorrono una alla volta con dei punti per passare dall'una all'altra, e link, tag e menzioni sulle schede appaiono come chip.",
