  "Locks, mentions and assignments so agents do not overwrite each other.": "Blocchi, menzioni e assegnazioni perché gli agenti non si sovrascrivano a vicenda.",
  "Long chats, light": "Chat lunghe, leggere",
  "Long enough. A few more characters make it stronger.": "Abbastanza lunga. Qualche carattere in più la rende più forte.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "I compiti più lunghi appaiono come elenco sopra la casella del messaggio: da iniziare, in corso, fatti.",
  "Longest sign-in": "Accesso più lungo",
  "Longest sign-in must be at least the inactivity time": "L'accesso più lungo deve essere almeno pari al tempo di inattività",
  "Look for tags that mean the same thing": "Cerca tag che significano la stessa cosa",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Esamina il progetto in questa cartella e salvalo in Memora: a cosa serve, come è fatto, come si avvia, le decisioni tecniche e tutto ciò che vale la pena ricordare. Crea una nota per argomento, in una cartella col nome del progetto dentro Projects.",
