  "Make an agent for each app or device you use. Each one gets its own key, so you can see what it does and turn it off on its own.": "Crea un agente per ogni app o dispositivo che usi. Ognuno riceve la propria chiave, così vedi cosa fa e puoi disattivarlo da solo.",
