  "Not created yet. Click to create it.": "Non ancora creata. Clicca per crearla.",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Non eseguito: Mnemo è in modalità Chiedi prima, quindi le modifiche attendono il via libera del proprietario. Chiedi con ask_owner (di' cosa cambierai; offri un'opzione con approve: true come «Sì, procedi»), poi fai la modifica dopo l'approvazione.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Non eseguito: Mnemo è in modalità Sola lettura, quindi le note non vengono modificate. Di' cosa cambieresti; il proprietario può passare a Chiedi prima o Auto nella chat.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Non eseguito: la chat è in modalità Chiedi prima, quindi un sub-agente non può modificare le note. Di' nella risposta cosa va cambiato; Mnemo lo chiede al proprietario.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Non eseguito: il proprietario ha disattivato {tool} per Mnemo (Impostazioni, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Non eseguito: il proprietario ha disattivato {tool} per i sub-agenti (Impostazioni, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Non completato: il proprietario ha interrotto questa risposta prima che lo strumento rispondesse.",
