  "Notes": "Note",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Note e bacheche condividono un'unica cornice di pagina con la stessa spaziatura su telefono, tablet e desktop, e i link in fondo a una nota hanno un unico aspetto ordinato che si richiude.",
  "Notes and boards, connected": "Note e bacheche, collegate",
  "Notes and images in the notes folder.": "Note e immagini nella cartella delle note.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Le note e i link tra loro appaiono qui come una mappa. La guida mostra come far salvare qui le conoscenze a un'AI, o come scrivere tu una nota.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Le note appaiono man mano che l'AI le salva e accendono il cervello. Questa pagina diventa la tua dashboard quando arriva la prima nota.",
  "Notes are not a password manager.": "Le note non sono un gestore di password.",
  "Notes changed in the app or in the folder": "Note modificate nell'app o nella cartella",
  "Notes folder": "Cartella delle note",
  "Notes folder switched": "Cartella delle note cambiata",
  "Notes from {name}": "Note da {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Le note in formato Obsidian Kanban si aprono come bacheche. Trascina schede e colonne con il mouse o con il dito, e ogni modifica finisce nella cronologia della nota.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Le note nella cartella attuale non vengono spostate, copiate né eliminate. Puoi tornare indietro da qui in qualsiasi momento.",
  "Notes inside a folder": "Note dentro una cartella",
  "Notes it found": "Note trovate",
  "Notes it saved": "Note salvate",
  "Notes must carry": "Le note devono avere",
  "Notes tagged #{tag}": "Note con tag #{tag}",
  "Notes that carry at least one tag": "Note con almeno un tag",
  "Notes that carry every tag": "Note con tutti i tag",
  "Notes that link nowhere and are linked from nowhere.": "Note che non rimandano a nulla e a cui nulla rimanda.",
  "Notes touched": "Note toccate",
  "Notes with a tag; the start of the tag is enough": "Note con un tag; basta l'inizio del tag",
  "Notes you delete wait here, so you can bring them back.": "Le note che elimini restano qui, così puoi recuperarle.",
  "Notes you or your AIs write show up here, newest first.": "Le note che scrivi tu o le tue AI appaiono qui, dalla più recente.",
  "Notes, folders and images in this chat": "Note, cartelle e immagini in questa chat",
  "Nothing deleted": "Nulla eliminato",
  "Nothing else in the last 24 hours.": "Nient'altro nelle ultime 24 ore.",
  "Nothing from {name} in the last 24 hours.": "Nulla da {name} nelle ultime 24 ore.",
  "Nothing here": "Niente qui",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Ancora nulla di nascosto: spunta gli agenti a cui nasconderlo. Per ora tutti i {n} agenti possono vederlo.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Ancora nulla di nascosto: spunta gli agenti a cui nasconderlo. Per ora l'unico agente può vederlo.",
  "Nothing in 24h": "Nulla in 24 ore",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Nulla nei nomi delle note, nelle cartelle o nei testi, e nulla scritto in modo simile. Prova con meno lettere, un'altra grafia o una parola dall'interno di una nota.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Nulla nelle ultime 24 ore. Ciò che fanno le tue AI appare qui mentre accade.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "Nulla nel registro corrisponde a «{name}». Mostro tutta l'attività.",
  "Nothing in this range": "Nulla in questo intervallo",
  "Nothing in your chats says “{query}”.": "Nulla nelle tue chat dice «{query}».",
  "Nothing is allowed. Turn something on, or pause the agent instead.": "Nulla è consentito. Attiva qualcosa, o metti in pausa l'agente.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Non si perde nulla: il testo attuale resta nella cronologia come v{n}, così puoi tornare indietro in qualsiasi momento.",
  "Nothing links here yet.": "Nulla rimanda ancora qui.",
  "Nothing matches": "Nessuna corrispondenza",
  "Nothing matches with these filters.": "Nessuna corrispondenza con questi filtri.",
  "Nothing matches “{q}” with these filters.": "Nessuna corrispondenza per «{q}» con questi filtri.",
  "Nothing matches “{q}”.": "Nessuna corrispondenza per «{q}».",
  "Nothing matches “{q}”. Maybe you meant one of these:": "Nessuna corrispondenza per «{q}». Forse intendevi uno di questi:",
  "Nothing matches.": "Nessuna corrispondenza.",
  "Nothing needs you right now.": "Nulla richiede il tuo intervento ora.",
  "Nothing recorded from this device yet.": "Ancora nulla registrato da questo dispositivo.",
