  "Off": "Spento",
  "Off for every AI.": "Disattivato per ogni AI.",
  "Off for every agent": "Disattivato per ogni agente",
  "Off: its models are hidden in chats": "Disattivato: i suoi modelli sono nascosti nelle chat",
  "Off: tap to switch on": "Spento: tocca per attivare",
  "Offline": "Offline",
  "Offline · Memora": "Offline · Memora",
  "Offline, retrying": "Offline, nuovo tentativo",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Gemini CLI più vecchio senza <code>gemini mcp add</code>: aggiungi il server a <code>~/.gemini/settings.json</code> sotto <code>mcpServers</code>, con <code>httpUrl</code> e la stessa intestazione.",
  "Older changes stay in History.": "Le modifiche più vecchie restano nella Cronologia.",
  "Older messages were left out to fit the model's context.": "I messaggi più vecchi sono stati esclusi per stare nel contesto del modello.",
  "Older than 30 days": "Più vecchio di 30 giorni",
  "Older than 7 days": "Più vecchio di 7 giorni",
  "Older than 90 days": "Più vecchio di 90 giorni",
  "Older versions of a note: read, compare, restore, and the trash.": "Versioni precedenti di una nota: leggi, confronta, ripristina, e il Cestino.",
  "Oldest entry": "Voce più vecchia",
  "On": "Acceso",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "Sul desktop, trascina il bordo dell’elenco chat o del pannello laterale per allargarlo o restringerlo. Ognuno ha una larghezza minima e la ricorda.",
  "On hover": "Al passaggio del mouse",
  "On its avatar, its sparks in the brain and every activity row.": "Sul suo avatar, nelle sue scintille nel cervello e in ogni riga di attività.",
  "On this page": "In questa pagina",
  "On: tap to switch off": "Acceso: tocca per disattivare",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "Attivo: {mnemo} annota ciò che coglie nelle chat. Disattivo: solo ciò che aggiungi qui. Salvato subito.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Una volta installata, l'app ha la sua icona, si apre a schermo intero e resta raggiungibile anche senza rete.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Una volta connesso, incolla questo in una nuova chat di quell'app. Dice all'AI di salvare in Memora ciò che sa.",
  "Once its app is set up, every call shows up here as it happens.": "Quando la sua app è configurata, ogni chiamata appare qui mentre accade.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Quando {name} è connesso, tutto ciò che legge, scrive e cerca appare qui, in diretta.",
  "One address": "Un indirizzo",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Un agente per app o dispositivo: la sua chiave, il suo nome in Attività, disattivabile da solo.",
  "One click": "Un clic",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Un dispositivo o una connessione, ad esempio 203.0.113.7. Cercando \"what is my IP\" vedi il tuo.",
  "One device or connection.": "Un dispositivo o una connessione.",
  "One folder of notes that you and every connected AI share.": "Una cartella di note condivisa da te e da ogni AI connessa.",
  "One is hidden by the folder rule.": "Uno è nascosto dalla regola della cartella.",
  "One key per agent, its own permissions.": "Una chiave per agente, con permessi propri.",
  "One last step": "Un ultimo passaggio",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Una sola memoria che ogni agente legge e scrive, e che puoi vedere, modificare e collegare interamente.",
  "One memory for every AI": "Una memoria per ogni AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Una nota mostra questa immagine; lì risulterà mancante. La cronologia delle versioni la conserva.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Una per riga. Appaiono tra i suggerimenti di una nuova chat, con l'etichetta Tue, e restano finché non le cambi.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Una memoria privata che tu e le tue app AI condividete, così non devi spiegare le cose due volte.",
  "One set of notes for every AI app": "Un solo insieme di note per ogni app AI",
  "Online": "Online",
  "Only PNG, JPEG, WebP and GIF images can be added": "Si possono aggiungere solo immagini PNG, JPEG, WebP e GIF",
  "Only in the current version": "Solo nella versione attuale",
  "Only in version {n}": "Solo nella versione {n}",
  "Only letters, digits and - _ / . can be used.": "Si possono usare solo lettere, cifre e - _ / .",
  "Only looks at notes; changes nothing.": "Guarda solo le note; non cambia nulla.",
  "Only looks things up and never writes. For agents with a read-only key.": "Consulta soltanto e non scrive mai. Per agenti con chiave di sola lettura.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Solo le immagini del tuo messaggio più recente vanno al modello di immagini, e lo scopri con un breve avviso.",
  "Only reads and answers; never changes notes": "Legge e risponde soltanto; non modifica mai le note",
  "Only the agents you pick. New agents can’t see it.": "Solo gli agenti che scegli. I nuovi agenti non possono vederlo.",
  "Only the first rule that fits a request counts.": "Conta solo la prima regola che corrisponde a una richiesta.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "All’inizio arrivano solo le domande più recenti; quelle precedenti compaiono scorrendo in alto o saltandoci dalla timeline.",
  "Only the ones I pick": "Solo quelli che scelgo",
