  "Operations": "Operazioni",
  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "Facoltativo. Poche parole su chi sei, su cosa lavori, come ti piacciono le risposte. {mnemo} le conserva e puoi cambiarle quando vuoi in Impostazioni.",
