  "Other files in it (such as images) are deleted too. This cannot be undone.": "Anche gli altri file al suo interno (come le immagini) vengono eliminati. Non si può annullare.",
  "Other servers in the file already? Add only the <code>memora</code> entry inside <code>mcpServers</code>.": "Ci sono già altri server nel file? Aggiungi solo la voce <code>memora</code> dentro <code>mcpServers</code>.",
