  "Past activity keeps the old name; new activity uses this one.": "L'attività passata mantiene il vecchio nome; la nuova usa questo.",
  "Paste both into the app and save.": "Incolla entrambi nell'app e salva.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Incollalo in un terminale e premi <kbd>Enter</kbd>, poi avvia Codex nello stesso terminale.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Incollalo in un terminale e premi <kbd>Enter</kbd>. Poi avvia Claude Code, o riavvialo: Memora si carica da solo.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Incollalo in un terminale e premi <kbd>Enter</kbd>. Poi avvia Gemini CLI, o riavvialo, e scrivi <code>/mcp</code> per vedere Memora.",
  "Paste it into the app where it asks for a key.": "Incollala nell'app dove chiede una chiave.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Incollalo nel file e salva, poi premi <b>Aggiorna</b>. Memora appare nell'elenco.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Incollalo nel file, salva e riavvia Claude Desktop. Serve Node.js su questo computer.",
