  "Pick it and the setup steps for that app follow, with {name}'s key filled in. For another app or device, make a new agent.": "Sceglila e seguono i passaggi di configurazione per quell'app, con la chiave di {name} già inserita. Per un'altra app o dispositivo, crea un nuovo agente.",
