  "Save failed": "Salvataggio non riuscito",
  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Salva in Memora ciò che ti ho raccontato della mia vita personale: i miei interessi, abitudini, obiettivi, le persone importanti per me e le cose a cui tengo. Metti queste note in una cartella chiamata Private, una nota per argomento, e collega le note correlate. Non salvare mai password, numeri di carta o altri segreti. Quando hai finito, dimmi cosa hai salvato.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Salva in Memora ciò che sai del mio lavoro: il mio ruolo, il mio team, i progetti a cui partecipo e a che punto sono, e le decisioni che abbiamo preso. Crea una nota per progetto o argomento e collegale tra loro.",
