  "When a chat's model fails (the provider is down, busy or out of credit), {mnemo} carries on with these, in this order, up to five. With none left, the chat shows the error and Try again. Saved at once.": "Quando il modello di una chat fallisce (provider non disponibile, occupato o senza credito), {mnemo} prosegue con questi, in quest'ordine, fino a cinque. Se non ne restano, la chat mostra l'errore e Riprova. Salvato subito.",
