  "You already have {who} for {app}. A separate agent per device keeps activity apart, so go ahead if this is another computer or setup.": "Hai già {who} per {app}. Un agente separato per dispositivo tiene distinta l'attività, quindi procedi se è un altro computer o un'altra configurazione.",
