  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "Ora hai una memoria a lungo termine grazie a Memora. Salva in Memora tutto ciò che sai di me dalle nostre conversazioni: chi sono, il mio lavoro, i progetti a cui partecipo, le mie preferenze e le decisioni importanti. Crea una nota per argomento in una cartella adatta e collega le note che vanno insieme. Quando hai finito, dimmi cosa hai salvato.",
