  "{mnemo} activity": "Attività di {mnemo}",
  "{mnemo} asks": "{mnemo} chiede",
  "{mnemo} asks before sub-agents run": "{mnemo} chiede prima di avviare i sub-agenti",
  "{mnemo} asks this model when you want a picture made.": "{mnemo} chiede a questo modello quando vuoi creare un'immagine.",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "Pulsante {mnemo} nascosto. Riportalo da Altro, Mostra il pulsante {mnemo}.",
  "{mnemo} button hidden. Show it again here or from More.": "Pulsante {mnemo} nascosto. Mostralo di nuovo qui o da Altro.",
  "{mnemo} could not write new ones just now. Check the model in Settings.": "{mnemo} non è riuscito a scriverne di nuovi ora. Controlla il modello in Impostazioni.",
  "{mnemo} hands pictures to this model when the chat model cannot see.": "{mnemo} passa le immagini a questo modello quando il modello della chat non può vederle.",
  "{mnemo} is working on this": "{mnemo} ci sta lavorando",
  "{mnemo} keeps only what you add": "{mnemo} conserva solo ciò che aggiungi",
  "{mnemo} knows nothing about you yet.": "{mnemo} non sa ancora nulla di te.",
  "{mnemo} looks after your notes": "{mnemo} si prende cura delle tue note",
  "{mnemo} may learn about you": "{mnemo} può imparare chi sei",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} lavora solo nelle tue note. Ogni modifica appare in Attività e si può annullare dalla Cronologia.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} legge il tuo vault in una nuova chat e conserva qui ciò che impara.",
  "{mnemo} settings saved": "Impostazioni di {mnemo} salvate",
  "{mnemo} settings: models and keys": "Impostazioni di {mnemo}: modelli e chiavi",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} avvia i sub-agenti da solo quando un compito si divide bene; non c'è nulla da configurare. Usano il tuo modello predefinito, poi quelli di riserva, a meno che tu non indichi un modello nella chat. Seguili, e cambia il loro modello, in Agenti in alto a destra nella chat. Consumano token propri, quindi con Chiedi prima {mnemo} chiede e indica più o meno quanti; con Auto partono e basta. Salvato subito.",
  "{mnemo} stopped it": "{mnemo} lo ha fermato",
  "{mnemo} will keep that in mind": "{mnemo} lo terrà presente",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} scrive nuovi suggerimenti dalle tue note recenti (i tuoi restano)",
  "{mnemo}'s own ({n})": "Di {mnemo} ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "Gli appunti di {mnemo} su come parlarti, letti in ogni chat. Clicca su uno per cambiarlo.",
  "{mnemo}, your notes agent": "{mnemo}, il tuo agente per le note",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} non può guardare le immagini; ha ricevuto i loro nomi. Imposta in Impostazioni un modello che legga le immagini per farle vedere.",
  "{model} cannot look at images; the image model described them for it.": "{model} non può guardare le immagini; il modello per le immagini le ha descritte per lui.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} non può leggere le immagini, quindi riceve solo i loro nomi. Imposta un modello che legga le immagini, oppure cambia il modello di questa chat.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} non può leggere le immagini, quindi ha ricevuto solo i loro nomi. Imposta un modello che legga le immagini, oppure cambia il modello di questa chat.",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} non può leggere le immagini, quindi il modello per le immagini le ha guardate per lui.",
  "{model} cannot read pictures, so the image model looks at them for it.": "{model} non può leggere le immagini, quindi il modello per le immagini le guarda per lui.",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "{model} non ha risposto ({why}); nuovo tentativo tra {wait} s ({n}/{total})…",
